import React from 'react';
import clsx from 'clsx';
import useDocusaurusContext from '@docusaurus/useDocusaurusContext';
import {useThemeConfig, useColorMode} from '@docusaurus/theme-common';
import type {ThemeConfig} from '@docusaurus/theme-common';
import {
  parseLanguage,
  useCodeWordWrap,
} from '@docusaurus/theme-common/internal';
import Highlight, {defaultProps, type Language} from 'prism-react-renderer';
import Line from '@theme/CodeBlock/Line';
import CopyButton from '@theme/CodeBlock/CopyButton';
import WordWrapButton from '@theme/CodeBlock/WordWrapButton';
import Container from '@theme/CodeBlock/Container';
import type {Props} from '@theme/CodeBlock/Content/String';

import styles from './styles.module.css';

export default function CodeBlockString({
  children,
  className: blockClassName = '',
  metastring,
  title: titleProp,
  showLineNumbers: showLineNumbersProp,
  language: languageProp,
}: Props): JSX.Element {
  const {
    prism: {defaultLanguage, magicComments},
  } = useThemeConfig();
  const language =
    languageProp ?? parseLanguage(blockClassName) ?? defaultLanguage;
  const wordWrap = useCodeWordWrap();
  const {colorMode} = useColorMode();
  const docusaurusContext = useDocusaurusContext();
  const siteThemeConfig = docusaurusContext.siteConfig
    .themeConfig as ThemeConfig;
  const prismSettings = siteThemeConfig.prism;
  const lightModeTheme = prismSettings.theme;
  const configuredDarkTheme = prismSettings.darkTheme;
  let prismTheme = lightModeTheme;
  if (colorMode === 'dark') {
    if (configuredDarkTheme) {
      prismTheme = configuredDarkTheme;
    } else {
      prismTheme = lightModeTheme;
    }
  } else {
    prismTheme = lightModeTheme;
  }

  const codeBlockTitleRegex = /title=(?<quote>["'])(?<title>.*?)\1/;
  let title = '';
  if (metastring) {
    const titleMatch = metastring.match(codeBlockTitleRegex);
    const extractedTitle = titleMatch?.groups?.title;
    if (typeof extractedTitle === 'string') {
      title = extractedTitle;
    }
  }
  if (!title) {
    if (titleProp) {
      title = titleProp;
    }
  }

  let showLineNumbers = false;
  if (typeof showLineNumbersProp === 'boolean') {
    showLineNumbers = showLineNumbersProp;
  } else if (metastring) {
    showLineNumbers = metastring.includes('showLineNumbers');
  }

  let code = children.replace(/\n$/, '');
  const lineClassNames: {[lineIndex: number]: string[]} = {};
  const metastringLinesRangeRegex = /\{(?<range>[\d,-]+)\}/;
  let parsedMetastringRange = false;
  const inclusiveRangeSeparators = ['-', '..', '\u2025'];
  const numericRangePattern =
    /^(-?\d+)(-|\.\.\.?|\u2025|\u2026|\u22EF)(-?\d+)$/;

  if (metastring && metastringLinesRangeRegex.test(metastring)) {
    const rangeMatch = metastring.match(metastringLinesRangeRegex);
    const linesRange = rangeMatch?.groups?.range;
    if (linesRange) {
      if (magicComments.length === 0) {
        throw new Error(
          `A highlight range has been given in code block's metastring (\`\`\` ${metastring}), but no magic comment config is available. Docusaurus applies the first magic comment entry's className for metastring ranges.`,
        );
      }
      const metastringRangeClassName = magicComments[0]!.className;
      const parsedRange: number[] = [];
      const rangeParts = linesRange.split(',');
      for (let partIndex = 0; partIndex < rangeParts.length; partIndex += 1) {
        const part = rangeParts[partIndex]!.trim();
        if (!part) {
          continue;
        }
        if (/^-?\d+$/.test(part)) {
          parsedRange.push(parseInt(part, 10));
        } else {
          const rangePair = part.match(numericRangePattern);
          if (rangePair) {
            const lhsToken = rangePair[1];
            const rhsToken = rangePair[3];
            const sep = rangePair[2];
            if (lhsToken && rhsToken && sep) {
              let lhs = parseInt(lhsToken, 10);
              let rhs = parseInt(rhsToken, 10);
              const incr = lhs < rhs ? 1 : -1;
              if (inclusiveRangeSeparators.includes(sep)) {
                rhs += incr;
              }
              for (let cursor = lhs; cursor !== rhs; cursor += incr) {
                parsedRange.push(cursor);
              }
            }
          }
        }
      }
      for (let rangeIndex = 0; rangeIndex < parsedRange.length; rangeIndex += 1) {
        const highlightedLine = parsedRange[rangeIndex]!;
        if (highlightedLine > 0) {
          lineClassNames[highlightedLine - 1] = [metastringRangeClassName];
        }
      }
      parsedMetastringRange = true;
    }
  }

  if (!parsedMetastringRange && language !== undefined) {
    const commentPatterns = {
      js: {start: '\\/\\/', end: ''},
      jsBlock: {start: '\\/\\*', end: '\\*\\/'},
      jsx: {start: '\\{\\s*\\/\\*', end: '\\*\\/\\s*\\}'},
      bash: {start: '#', end: ''},
      html: {start: '<!--', end: '-->'},
      lua: {start: '--', end: ''},
      wasm: {start: '\\;\\;', end: ''},
      tex: {start: '%', end: ''},
    } as const;
    type CommentType = keyof typeof commentPatterns;
    const commentTypeByLanguage: {[lang: string]: CommentType[]} = {
      js: ['js', 'jsBlock'],
      javascript: ['js', 'jsBlock'],
      ts: ['js', 'jsBlock'],
      typescript: ['js', 'jsBlock'],
      jsx: ['js', 'jsBlock', 'jsx'],
      tsx: ['js', 'jsBlock', 'jsx'],
      html: ['js', 'jsBlock', 'html'],
      python: ['bash'],
      py: ['bash'],
      bash: ['bash'],
      markdown: ['html', 'jsx', 'bash'],
      md: ['html', 'jsx', 'bash'],
      tex: ['tex'],
      latex: ['tex'],
      matlab: ['tex'],
      lua: ['lua'],
      haskell: ['lua'],
      sql: ['lua'],
      wasm: ['wasm'],
