              }
            }
          }
        }
      }
      for (
        let rangeIndex = 0;
        rangeIndex < parsedBlockRange.length;
        rangeIndex += 1
      ) {
        const highlightedLine = parsedBlockRange[rangeIndex]!;
        if (lineClassNames[highlightedLine]) {
          lineClassNames[highlightedLine]!.push(className);
        } else {
          lineClassNames[highlightedLine] = [className];
        }
      }
    }
  }

  let languageClassName = blockClassName;
  if (language) {
    if (!blockClassName.includes(`language-${language}`)) {
      languageClassName = clsx(blockClassName, `language-${language}`);
    }
  }
  const highlightLanguage = (language ?? 'text') as Language;
  const canToggleWordWrap = wordWrap.isEnabled || wordWrap.isCodeScrollable;

  return (
    <Container as="div" className={languageClassName}>
      {title ? <div className={styles.codeBlockTitle}>{title}</div> : null}
      <div className={styles.codeBlockContent}>
        <Highlight
          {...defaultProps}
          theme={prismTheme}
          code={code}
          language={highlightLanguage}>
          {({className, tokens, getLineProps, getTokenProps}) => (
            <pre
              /* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */
              tabIndex={0}
              ref={wordWrap.codeBlockRef}
              className={clsx(className, styles.codeBlock, 'thin-scrollbar')}>
              <code
                className={clsx(
                  styles.codeBlockLines,
                  showLineNumbers && styles.codeBlockLinesWithNumbering,
                )}>
                {tokens.map((line, i) => (
                  <Line
                    key={i}
                    line={line}
                    getLineProps={getLineProps}
                    getTokenProps={getTokenProps}
                    classNames={lineClassNames[i]}
                    showLineNumbers={showLineNumbers}
                  />
                ))}
              </code>
            </pre>
          )}
        </Highlight>
        <div className={styles.buttonGroup}>
          {canToggleWordWrap ? (
            <WordWrapButton
              className={styles.codeButton}
              onClick={() => wordWrap.toggle()}
              isEnabled={wordWrap.isEnabled}
            />
          ) : null}
          <CopyButton className={styles.codeButton} code={code} />
        </div>
      </div>
    </Container>
  );
}

